<?php
namespace App\Models\Sla; use App\Models\BusinessHourPolicy; use App\Models\Concerns\HasPublicUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class SlaPolicy extends Model {use HasPublicUuid;protected $fillable=['name','description','active','priority','calendar_mode','business_hours_policy_id','targets','pause_statuses','approaching_percentage','conditions','created_by'];protected function casts():array{return ['active'=>'boolean','targets'=>'array','pause_statuses'=>'array','conditions'=>'array'];}public function businessHours():BelongsTo{return $this->belongsTo(BusinessHourPolicy::class,'business_hours_policy_id');}public function instances():HasMany{return $this->hasMany(SlaInstance::class);}}
